steps.script:
var st = GameState.state
var g = st.units.U_CUSTODIAN_GUARD_B
var k = 0
for m in g.models:
	m.position = {"x": 690.0 + float(k) * 65.0, "y": 880.0}
	k += 1
if g.has("flags"):
	g.flags.erase("last_shot_idx")
	g.flags.erase("shot_recently")
var s = st.units.U_CUSTODIAN_GUARD_A_P2
var j = 0
for m in s.models:
	m.position = {"x": 1270.0 + float(j) * 65.0, "y": 1640.0}
	j += 1
for uid in st.units:
	if uid == "U_CUSTODIAN_GUARD_B" or uid == "U_CUSTODIAN_GUARD_A_P2":
		continue
	var u = st.units[uid]
	var q = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 600.0 + 40.0 * float(q % 5), "y": 300.0}
		else:
			m.position = {"x": 1500.0 + 40.0 * float(q % 6), "y": 2300.0 - 40.0 * float(q / 6)}
		q += 1
# Layout drift guard (engine, not the AI): from the straight move's end
# (4.2" south, y 1048.5) AND from the start, the squad has no eligible target.
var blind = true
for y in [1048.5, 880.0]:
	var snap = GameState.create_snapshot()
	var su = snap.units.U_CUSTODIAN_GUARD_B
	var kk = 0
	for m in su.models:
		m.position = Vector2(690.0 + 65.0 * float(kk), y)
		kk += 1
	su.flags["in_engagement"] = false
	if RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size() > 0:
		blind = false
return blind

# FIX_MOVE_FOR_SHOT ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/move_for_shot_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

# Engine truth on the suggested move: the destinations the AI plans give the
# squad U_CUSTODIAN_GUARD_A_P2 as an eligible target (04.02).
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var snap = GameState.create_snapshot()
var su = snap.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
for m in su.models:
	if dests.has(m.id):
		m.position = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
su.flags["in_engagement"] = false
var sees = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, false, {"U_CUSTODIAN_GUARD_A_P2": true}).has("U_CUSTODIAN_GUARD_A_P2")
var any_target = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size() > 0
return sees

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_MOVE_FOR_SHOT at 0 —
# the straight move, no note, no reason suffix, and (engine) no target from it.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var snap = GameState.create_snapshot()
var su = snap.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
for m in su.models:
	if dests.has(m.id):
		m.position = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
su.flags["in_engagement"] = false
var sees = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, false, {"U_CUSTODIAN_GUARD_A_P2": true}).has("U_CUSTODIAN_GUARD_A_P2")
var any_target = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size() > 0
var desc = str(d.get("_ai_description", ""))
return (not str(d.get("_ai_move_adjustments", [])).contains("for a shot next phase")) and not any_target and desc.contains("moves toward obj_center") and not desc.contains("for a shot at")

# ...and reloading the profile restores the spot.
var f = FileAccess.open("res://tests/bench_profiles/move_for_shot_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var snap = GameState.create_snapshot()
var su = snap.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
for m in su.models:
	if dests.has(m.id):
		m.position = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
su.flags["in_engagement"] = false
var sees = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, false, {"U_CUSTODIAN_GUARD_A_P2": true}).has("U_CUSTODIAN_GUARD_A_P2")
var any_target = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size() > 0
return str(d.get("_ai_move_adjustments", [])).contains("for a shot next phase") and sees

# The AI's own execution path: stage + confirm through AIPlayer, then ask
# the ENGINE where the models are and what they can target.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": "U_CUSTODIAN_GUARD_B", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_method("has_pending_stratagem_window") and ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var obj = {}
for o in GameState.state.board.objectives:
	if str(o.get("id", "")) == "obj_center":
		obj = o
var on_obj = 0
for m in u.models:
	if m.get("alive", true) and MissionManager.model_in_objective_range(m, obj):
		on_obj += 1
var snap = GameState.create_snapshot()
snap.units.U_CUSTODIAN_GUARD_B.flags["in_engagement"] = false
var n_targets = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size()
return bool(u.get("flags", {}).get("moved", false)) and on_obj >= 1 and n_targets >= 1

# Draw the sight-line overview from the moved squad (what holding L shows):
# the line to the enemy squad must read 'targetable' — the overlay answers
# the same question as the target list.
var main_n = tree.root.get_node("Main")
var lv = tree.root.get_node_or_null("Main/BoardRoot/LoSDebugVisual")
if lv == null:
	main_n._toggle_los_debug()
	lv = tree.root.get_node_or_null("Main/BoardRoot/LoSDebugVisual")
if lv == null:
	return "no overlay"
lv.set_debug_enabled(true)
lv.show_overview("U_CUSTODIAN_GUARD_B")
for ol in lv.overview_lines:
	if str(ol["tgt"]) == "U_CUSTODIAN_GUARD_A_P2":
		return str(ol["verdict"])
return "no line"

var lv = tree.root.get_node_or_null("Main/BoardRoot/LoSDebugVisual")
if lv != null:
	lv.hide_overview()
	lv.set_debug_enabled(false)
tree.current_scene.reset_camera()
return true

# The shot is real: in the Shooting phase the AI's own decision for the squad
# shoots U_CUSTODIAN_GUARD_A_P2 (the flag-off move would have had no target).
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var dd = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_CUSTODIAN_GUARD_B"}], 1)
var hit = false
for a in dd.get("payload", {}).get("assignments", []):
	if str(a.get("target_unit_id", "")) == "U_CUSTODIAN_GUARD_A_P2":
		hit = true
return str(dd.get("type", "")) == "SHOOT" and hit
